import { reconcile, filterDefaults, picksUntilTurn, clearFieldError, setFieldError, syncDraftPanelSemantics } from './ui-state.js';
const $ = (s,root=document) => root.querySelector(s);
const app=$('#app'), dialog=$('#dialog');
const draftMobile=matchMedia('(max-width:760px)');
draftMobile.addEventListener('change',()=>syncDraftPanelSemantics(document,draftMobile.matches));
const e = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={ crown:'M3 6l4 4 5-7 5 7 4-4-2 13H5L3 6z M7 22h10',home:'M3 10l9-7 9 7v11h-6v-7H9v7H3z', trophy:'M7 3h10v7a5 5 0 0 1-10 0V3z M7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 3v6m-4 0h8', mail:'M3 5h18v14H3z m0 0 9 8 9-8',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0z M4 21v-2a8 8 0 0 1 16 0v2',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M12 7v5l3 2',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',down:'m6 9 6 6 6-6',up:'m6 15 6-6 6 6',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8z M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chat:'M3 4h18v13H8l-5 4V4z',activity:'M3 12h4l3-8 4 16 3-8h4',logout:'M9 3H3v18h6m5-15 6 6-6 6m-7-6h13',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0z m-2 4 7 7'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.trophy}"/></svg>`;
const brand=()=>`<a class="brand" href="${S.user?'/home':'/'}"><span class="brand-mark">${icon('crown')}</span><span>League of Champions<span class="brand-sub">One league. Every season.</span></span></a>`;
const avatar=(name,orange=false)=>`<span class="avatar ${orange?'orange':''}" aria-hidden="true">${e(name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>`;
const button=(label,action,klass='',attrs='')=>`<button class="button ${klass}" type="button" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,url,klass='')=>`<a class="button ${klass}" href="${url}">${label}</a>`;
const status=l=>`<span class="pill ${l.status}"><span class="dot"></span>${{scheduled:'Scheduled',live:'Draft live',paused:'Paused',complete:'Draft complete'}[l.status]}</span>`;
const sample=l=>l.sample?'<span class="sample-label">Sample league</span>':'';
const empty=(title,description,action='')=>`<div class="empty">${icon('trophy')}<h3>${e(title)}</h3><p>${e(description)}</p>${action}</div>`;
const head=(title,description,action='',eyebrow='YOUR SEASON, ALL TOGETHER')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1 tabindex="-1">${e(title)}</h1><p>${e(description)}</p></div>${action}</div>`;
const option=(value,label,selected)=>`<option value="${e(value)}" ${String(value)===String(selected)?'selected':''}>${e(label)}</option>`;
const field=(name,label,value='',type='text',extra='',hint='')=>`<label class="field"><span>${label}</span><input name="${name}" id="${name}" type="${type}" value="${e(value)}" ${extra} ${hint?`aria-describedby="${name}-hint"`:''}>${hint?`<small id="${name}-hint">${hint}</small>`:''}</label>`;
const select=(name,label,options,extra='')=>`<label class="field"><span>${label}</span><select name="${name}" id="${name}" ${extra}>${options}</select></label>`;
const textArea=(name,label,value='',hint='')=>`<label class="field"><span>${label}</span><textarea name="${name}" id="${name}" maxlength="500" ${hint?`placeholder="${e(hint)}"`:''}>${e(value)}</textarea></label>`;
const formError=()=>'<div class="form-error" role="alert"></div>';
const zones=[...new Set([Intl.DateTimeFormat().resolvedOptions().timeZone,'America/New_York','America/Chicago','America/Denver','America/Los_Angeles','Europe/London','Europe/Paris','Asia/Tokyo','Australia/Sydney','UTC'])];
let S={user:null,leagues:[],invitations:[],sports:[],revision:-1}, route=location.pathname, busy=false, connected=true, offset=0, intended='/home',lastFocus=null, pendingRender=false;
let ui={selected:null,draftTab:'available',poolSearch:'',poolSport:'',poolAll:false,leagueSearch:'',sort:'rank',sortAsc:true,pickSearch:'',pickSport:'',pickRound:'',filtersLeague:null};
const scrolls=new Map();
let lastSync=Date.now(),renderEpoch=0;
try{intended=sessionStorage.getItem('loc-intent')||'/home';}catch{}
function keepIntent(url){intended=url;try{sessionStorage.setItem('loc-intent',url);}catch{}}

const emailEnabled=()=>S.emailMode&&S.emailMode!=='disabled';
const emailCopy=()=>S.emailMode==='preview'?'Testing mailbox only — no email is sent.':emailEnabled()?'Email delivery is enabled. Links open this workspace on its host computer.':'Email delivery is not configured. Invitations stay in this local app.';
const filterKey=()=> 'loc-filters:'+S.user?.id;
function saveFilters(){try{const saved=JSON.parse(sessionStorage.getItem(filterKey())||'{}');saved.leagueSearch=ui.leagueSearch;if(ui.filtersLeague)saved[ui.filtersLeague]=Object.fromEntries(Object.keys(filterDefaults).map(k=>[k,ui[k]]));sessionStorage.setItem(filterKey(),JSON.stringify(saved));}catch{}}
function loadFilters(id){let saved={};try{saved=JSON.parse(sessionStorage.getItem(filterKey())||'{}');}catch{}Object.assign(ui,filterDefaults,saved[id]||{});ui.leagueSearch=saved.leagueSearch||'';ui.filtersLeague=id;ui.selected=null;}
function turnHint(l){const distance=picksUntilTurn(l,S.user.id);return distance===null?'Your roster is complete.':distance===0?'You have the next pick.':`Your turn in ${distance} ${distance===1?'pick':'picks'}.`;}
function readiness(l){return `<section class="panel readiness"><h2>Get your league ready</h2><ul class="setup-checklist"><li>${l.members.length===l.capacity?'✓':'○'} ${l.members.length} of ${l.capacity} managers joined</li><li>${l.scheduled?'✓':'○'} ${l.scheduled?date(l.scheduled):'Draft date not set'}</li><li>✓ ${l.sports.length} sports · ${l.capacity*l.sports.length} picks · ${l.timer} seconds per pick</li></ul><div class="button-row">${l.commissioner?link('Invite managers',leagueUrl(l,'settings')+'#invitations','primary')+link('Schedule draft',leagueUrl(l,'settings')+'#scheduled','ghost'):link('Prepare your queue',leagueUrl(l,'draft'),'primary')}${link('Review rules',leagueUrl(l,'rules'),'ghost')}</div></section>`;}
function reconcileSelection(){if(!dialog.open||!$('.selection-panel',dialog))return;const l=league();if(!l)return;reconcile($('#selection-live',dialog),`<p class="small muted">${l.status==='live'?turnHint(l):l.status==='paused'?'Draft paused':l.status==='complete'?'Draft complete':'Draft scheduled'} · <span data-selection-clock></span></p>${selection(l,true)}`);tick();}

const draftKey=form=>'loc-form:'+S.user?.id+':'+route+':'+form.dataset.form;
function rememberForm(form){if(!form||!['create','settings','account','invite','score','chat'].includes(form.dataset.form))return;try{const data=[...new FormData(form)];sessionStorage.setItem(draftKey(form),JSON.stringify(data));}catch{}}
function restoreForms(){document.querySelectorAll('form[data-form]').forEach(form=>{try{const raw=sessionStorage.getItem(draftKey(form));if(!raw)return;const data=JSON.parse(raw);for(const input of form.elements){if(!input.name||input.type==='password')continue;const vals=data.filter(([name])=>name===input.name).map(([,v])=>v);if(input.type==='checkbox')input.checked=vals.includes(input.value);else if(vals.length)input.value=vals[0];}}catch{}});}

function date(value,options={}) {return value?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short',timeZone:S.user?.zone||'America/New_York',...options}).format(new Date(value)):'Not scheduled';}
function updateState(data){const userChanged=S.user?.id!==data.user?.id;S=data;offset=data.serverTime-Date.now();lastSync=Date.now();if(userChanged)loadFilters(league()?.id||null);}
function setConnected(value){if(connected===value)return;connected=value;const old=$('#connection');if(value)old?.remove();else{const b=document.createElement('div');b.id='connection';b.className='notice warning connection-banner';b.setAttribute('role','alert');b.innerHTML=`<span>Connection lost. Your work is still here. Last synced ${e(date(lastSync))}. Reconnecting…</span> ${button('Retry now','retry-connection','ghost')}`;app.prepend(b);}document.querySelectorAll('[data-mutation],[type=submit]').forEach(b=>{if(!value){b.dataset.offlineDisabled=String(b.disabled);b.disabled=true;}else{b.disabled=b.dataset.offlineDisabled==='true';delete b.dataset.offlineDisabled;}});}
async function request(url,data){const response=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(10000)});const result=await response.json();if(!response.ok)throw Object.assign(new Error(result.error),{status:response.status,field:result.field});return result;}
async function mutate(url,data,success,form){if(busy)return;if(!connected){const err=new Error('Reconnect before saving. Your changes are still here.');if(form)showError(form,err);else toast(err.message);return null;}busy=true;const epoch=renderEpoch;const buttons=[...(form||document).querySelectorAll('[type=submit],[data-mutation]')];const disabledBefore=buttons.map(b=>b.disabled);buttons.forEach(b=>b.disabled=true);if(form)form.setAttribute('aria-busy','true');announce('Saving changes…');try{const result=await request(url,data);updateState(result);setConnected(true);announce('Changes saved.');if(form)try{sessionStorage.removeItem(draftKey(form));}catch{}if(success)await success(result);return result;}catch(err){announce('Changes were not saved. '+err.message);if(!err.status)setConnected(false);if(form)showError(form,err);else toast(err.message);if(err.status===409){if(dialog.open&&$('.selection-panel',dialog))closeDialog();await refresh(true);}if(err.status===401&&S.user){keepIntent(route);authDialog('login');}return null;}finally{busy=false;buttons.forEach((b,i)=>{if(b.isConnected&&renderEpoch===epoch)b.disabled=disabledBefore[i]||!connected;});if(form)form.removeAttribute('aria-busy');}}
function showError(form,err){const target=$('.form-error',form);if(target){target.className='form-error notice error';target.textContent=err.message;}if(!err.field||!setFieldError(form,err.field,err.message)){target?.setAttribute('tabindex','-1');target?.focus();}}
function toast(message,extra=''){const t=$('#toast');t.innerHTML=e(message)+extra;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.replaceChildren(),extra?15000:6000);}
function announce(text){$('#announcer').textContent=text;}
function showDialog(title,body){if(!dialog.open)lastFocus=document.activeElement;$('#dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2>${button(icon('close'),'close','icon-button ghost','aria-label="Close dialog"')}</div>${body}</div>`;if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>($('input:not([type=checkbox]),select',dialog)||$('button',dialog))?.focus());}
function closeDialog(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();else $('#main h1')?.focus();}
dialog.addEventListener('cancel',()=>{requestAnimationFrame(()=>{if(lastFocus?.isConnected)lastFocus.focus();});});
function navigate(url,{replace=false,restore=false}={}){saveFilters();scrolls.set(route,scrollY);if(!restore)history[replace?'replaceState':'pushState']({},'',url);route=location.pathname;render();if(restore)window.scrollTo(0,scrolls.get(route)||0);else{window.scrollTo(0,0);$('#main h1')?.focus({preventScroll:true});}if(location.hash){const target=document.getElementById(location.hash.slice(1));if(target){target.scrollIntoView({block:'center'});target.focus({preventScroll:true});}}}
function league(){return S.leagues.find(l=>l.id===route.split('/')[2]);}
function leagueUrl(l,tab='standings'){return `/leagues/${l.id}/${tab}`;}
function primaryAction(l){return l.status==='complete'?['View standings',leagueUrl(l)]:[l.status==='live'?'Join live draft':l.status==='paused'?'Return to draft':'Prepare for draft',leagueUrl(l,'draft')];}
function navItems(){const active=route.startsWith('/leagues')?'leagues':route.split('/')[1];return [['home','Home','home'],['leagues','My leagues','trophy'],['invitations','Invitations','mail'],['account','Account','user']].map(([path,label,ico])=>`<a class="nav-item" href="/${path}" ${active===path?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${path==='invitations'&&S.invitations.some(i=>i.status==='pending')?`<span class="nav-count">${S.invitations.filter(i=>i.status==='pending').length}</span>`:''}</a>`).join('');}
function shell(content){return `<div class="app-layout"><aside class="sidebar">${brand()}<div><p class="nav-label">WORKSPACE</p><nav class="global-nav" aria-label="Main navigation">${navItems()}</nav></div><div class="sidebar-bottom"><div class="local-note">${icon('shield')} Local workspace<br>Saved on this computer.<br>${S.user.sample?'Sample data · explore freely.':'Invitations stay in this local app.'}</div><a class="profile-nav" href="/account">${avatar(S.user.name,true)}<span><strong>${e(S.user.name)}</strong><small>${S.user.sample?'Sample account':'Local account'}</small></span></a></div></aside><div class="workspace"><header class="app-topbar">${brand()}<span class="topbar-context">Workspace <span class="muted"> / </span> ${route.startsWith('/leagues')?'My leagues':e({home:'Home',invitations:'Invitations',account:'Account'}[route.split('/')[1]]||'Home')}</span><span class="local-indicator">${icon('shield')} Local preview ${S.user.sample?' · Sample data':''}</span><a class="button ghost" href="/account" aria-label="Open account">${avatar(S.user.name)}</a></header><main class="content" id="main">${emailEnabled()&&!S.user.sample&&!S.user.verified?`<div class="notice warning section-head"><span>Verify your email before accepting invitations.</span>${link('Review email status','/account','ghost')}</div>`:''}${content}</main></div><nav class="mobile-nav" aria-label="Mobile navigation">${navItems()}</nav></div>`;}
function landing(){return `<header class="public-header">${brand()}<nav aria-label="Public navigation"><a class="text-link" href="#how-it-works">How it works</a><a class="text-link" href="#rules">Scoring</a>${button('Sign in','login','ghost')}${button('Get started','signup','primary')}</nav></header><main id="main"><section class="hero"><img class="hero-art" src="/assets/loc-hero.png" alt="" fetchpriority="high"><div class="hero-copy"><p class="eyebrow accent">THE GAME DOESN'T END WITH ONE SEASON</p><h1>One league.<br>Every season.<br><span class="accent">Your championship.</span></h1><p>Draft entire teams across your favorite sports. Follow their postseason runs. Turn every season into a rivalry worth keeping.</p><div class="button-row">${button(`Create your league ${icon('arrow')}`,'signup','primary','data-intent="/leagues/new"')}${button('Explore a sample league','demo','ghost','data-mutation')}</div><p class="small">Local preview · ${emailEnabled()?emailCopy():'no email sent'} · scores entered by commissioners</p></div></section><section class="public-section" id="how-it-works"><p class="eyebrow">LESS MANAGEMENT. MORE RIVALRY.</p><h2>A whole year of something to play for.</h2><p>One team per sport. One shared leaderboard. One champion.</p><div class="steps">${[['01','Make it your league','Choose your sports, invite your people, and set your draft.'],['02','Draft your contenders','Build a queue and pick entire teams in a live snake draft.'],['03','Make every season count','Earn placement points and championship bonuses across every sport.']].map(([n,t,p])=>`<article class="panel"><span class="step-num">${n}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="public-section" id="rules"><p class="eyebrow">NOTHING HIDDEN IN THE RULEBOOK</p><h2>Clear rules. Bragging rights earned.</h2>${rules()}</section></main><footer class="public-footer">League of Champions · Local preview. Your data stays on this computer.</footer>`;}
function leagueRow(l){const [label,url]=primaryAction(l), rank=l.standings.find(r=>r.id===S.user.id)?.rank;return `<article class="league-row"><div class="league-emblem">${icon('trophy')}</div><div class="league-info"><h3><a href="${leagueUrl(l)}">${e(l.name)}</a></h3><p>${l.season} season · ${l.members.length}/${l.capacity} managers · ${l.sports.length} sports${l.status==='complete'?` · Your rank #${rank}`:''}</p>${sample(l)}</div><div class="league-right">${status(l)}<a class="button ghost" href="${url}" aria-label="${e(label+' · '+l.name)}">${label} ${icon('arrow')}</a></div></article>`;}
function invitationCard(i,compact=false){const l=i.league;if(!l)return '';return `<article class="${compact?'invite-preview':'panel'}"><div class="section-head"><h3>${e(l.name)}</h3><span class="pill">${l.season}</span></div><p>${e(l.owner)} invited you to a ${l.capacity}-manager league.</p><div class="sport-tags">${l.sports.map(s=>`<span class="sport-tag">${e(s)}</span>`).join('')}</div><p class="small">Draft: ${date(l.scheduled)} · ${l.joined}/${l.capacity} joined</p><div class="button-row section-space">${i.status==='pending'?button('Accept invitation','invite-accept','primary',`data-id="${i.id}" data-mutation`)+button('Decline','invite-decline','ghost',`data-id="${i.id}" data-mutation`):button('Restore invitation','invite-undo','ghost',`data-id="${i.id}" data-mutation`)}</div></article>`;}
function home(){const next=[...S.leagues].sort((a,b)=>({live:0,paused:1,scheduled:2,complete:3}[a.status]-{live:0,paused:1,scheduled:2,complete:3}[b.status])||(a.scheduled||Infinity)-(b.scheduled||Infinity))[0];const invites=S.invitations.filter(i=>i.status==='pending');return head(`Welcome back, ${S.user.name.split(' ')[0]}.`,'A little strategy. A lot to look forward to.',link(`${icon('plus')} Create league`,'/leagues/new','ghost'))+(next?`<section class="next-card"><div><p class="eyebrow">${next.status==='live'?'YOU’RE UP NEXT':next.status==='complete'?'YOUR SEASON AT A GLANCE':'NEXT ON YOUR CALENDAR'}</p>${status(next)}<h2>${e(next.name)}</h2><p>${next.status==='complete'?'See how your contenders stack up.':next.status==='live'?`${e(next.current?.name)} is on the clock.`:next.status==='paused'?'The draft is paused. Your queue is saved.':`${date(next.scheduled)} · ${next.timer} seconds per pick`}</p></div><div class="next-action">${link(primaryAction(next)[0]+icon('arrow'),primaryAction(next)[1],'primary')}</div></section>`:`<section class="panel section-space">${empty('Your first championship starts here.','Create a league for your friends, or check your invitations.',link('Create a league','/leagues/new','primary')+link('View invitations','/invitations','ghost'))}</section>`)+`<div class="dashboard-grid"><section><div class="section-head"><h2>My leagues <small>${S.leagues.length} total</small></h2><a class="text-link" href="/leagues">View all ${icon('arrow')}</a></div><div class="league-list">${S.leagues.slice(0,3).map(leagueRow).join('')||empty('No leagues yet','Your leagues will appear here.')}</div><div class="panel section-space insight">${icon('crown')}<div><h3>Build your roster. Enjoy the season.</h3><p>One team per sport. Add a few favorites to your queue before the draft begins.</p></div></div></section><aside class="stack"><section class="panel"><div class="section-head"><h2>Invitations <small>${invites.length}</small></h2>${icon('mail')}</div>${invites.slice(0,2).map(i=>invitationCard(i,true)).join('')||empty('All caught up','New league invitations will appear here.')}<a class="text-link" href="/invitations">Manage invitations ${icon('arrow')}</a></section><section class="panel insight">${icon('shield')}<div><h3>${S.user.sample?'A space to try things out':'Your local workspace'}</h3><p>${S.user.sample?'These leagues and results are illustrative. Create a personal account to begin with a clean slate.':'Your leagues, queues, and settings are saved on this computer. Local invitations appear when the recipient signs in here.'}</p></div></section></aside></div>`;}
function leaguesPage(){const filtered=S.leagues.filter(l=>l.name.toLowerCase().includes(ui.leagueSearch.toLowerCase()));return head('My leagues','Every rivalry, in one place.',link(`${icon('plus')} Create league`,'/leagues/new','primary'))+`<div class="filter-bar"><label class="field search-field"><span>Find a league</span><input data-filter="leagueSearch" id="leagueSearch" type="search" placeholder="Search by league name" value="${e(ui.leagueSearch)}"></label></div><p class="small muted section-head">${filtered.length} ${filtered.length===1?'league':'leagues'}</p><div class="league-list">${filtered.map(leagueRow).join('')||empty(ui.leagueSearch?'No matching leagues':'No leagues yet',ui.leagueSearch?'Try a different name or clear your search.':'Create your first league or check your invitations.',ui.leagueSearch?button('Clear search','clear-league','ghost'):link('Create league','/leagues/new','primary'))}</div>`;}
function invitationsPage(){const pending=S.invitations.filter(i=>i.status==='pending'),declined=S.invitations.filter(i=>i.status==='declined');return head('Invitations','Your next rivalry might be waiting here.')+`<div class="notice section-head">${emailCopy()}</div><div class="stack">${pending.map(i=>invitationCard(i)).join('')||`<section class="panel">${empty('You’re all caught up','New invitations will appear here when a commissioner invites your account email.')}</section>`}${declined.length?`<details class="panel"><summary>Declined invitations (${declined.length})</summary><div class="stack section-space">${declined.map(i=>invitationCard(i,true)).join('')}</div></details>`:''}</div>`;}
function dateInput(value){if(!value)return '';const parts=new Intl.DateTimeFormat('sv-SE',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:S.user?.zone||zones[0],hourCycle:'h23'}).format(new Date(value));return parts.replace(' ','T');}
function toInstant(value){if(!value)return '';const desired=new Date(value+'Z').getTime();let result=desired;for(let i=0;i<3;i++){const represented=new Date(dateInput(result)+'Z').getTime();result+=desired-represented;}if(dateInput(result)!==value)throw Object.assign(new Error('That local time does not exist due to a clock change. Choose another time.'),{field:'scheduled'});return new Date(result).toISOString();}
function draftFields(l={}){return `${field('scheduled',`Draft date and time · ${e(S.user.zone)}`,dateInput(l.scheduled),'datetime-local','','Leave blank to schedule later. Clock starts only when the commissioner starts the draft.')}<div class="form-grid">${select('timer','Time per pick',[30,60,90,120].map(t=>option(t,`${t} seconds`,l.timer||60)).join(''))}${select('order','Draft order',option('random','Randomize when draft starts',l.order||'random')+option('manual','Commissioner sets order',l.order))}</div><p class="small muted">Snake draft · one team per sport. At timeout, your first eligible queued team is picked; otherwise the highest-ranked eligible team in this local catalog is picked. Catalog order is illustrative, not a prediction.</p>`;}
function createPage(){return head('Create a league','Start with the essentials. You can invite managers and schedule your draft next.','', 'MAKE IT YOURS')+`<form class="panel form-container" data-form="create">${formError()}${field('name','League name','','text','required minlength="3" maxlength="120" placeholder="e.g. Sunday Club"')}<div class="form-grid">${field('season','Season',new Date().getFullYear(),'number','required min="2026" max="2100"')}${field('capacity','Managers',8,'number','required min="4" max="12" data-summary')}</div><fieldset><legend>Sports included <span class="muted">· select at least one</span></legend><div class="sport-options">${S.sports.map(s=>`<label class="sport-option"><input type="checkbox" name="sports" value="${e(s)}" data-summary>${e(s)}</label>`).join('')}</div></fieldset><div class="notice" id="setup-summary">Choose your sports to see your draft size.</div><details class="disclosure"><summary>Draft options & optional description</summary>${draftFields()}${textArea('description','Description (optional)')}</details><p class="small muted">Private league · only invited managers can join. You’ll be the commissioner.</p><div class="form-footer">${link('Cancel','/leagues','ghost')}<button class="button primary" type="submit">Create league ${icon('arrow')}</button></div></form>`;}
function leagueHeader(l,tab){return `<nav class="breadcrumb" aria-label="Breadcrumb"><a href="/leagues">My leagues</a><span aria-hidden="true">/</span><span>${e(l.name)}</span></nav><div class="page-head league-page-head"><div><div class="button-row">${status(l)}${sample(l)}</div><h1 tabindex="-1" class="section-space">${e(l.name)}</h1><p>${l.season} season · ${l.members.length}/${l.capacity} managers · Commissioner ${e(l.members.find(m=>m.id===l.owner)?.name)}</p></div><div class="league-heading-actions">${select('leagueSwitch','Switch league',S.leagues.map(x=>option(x.id,x.name,l.id)).join(''),'data-league-switch')}${l.status!=='complete'?link(primaryAction(l)[0],leagueUrl(l,'draft'),'primary'):''}</div></div><nav class="league-nav" aria-label="League navigation">${[['standings','Standings'],['roster','My roster'],['results','Draft results'],['activity','Activity'],['rules','Rules'],...(l.commissioner?[['settings','Settings']]:[])].map(([key,label])=>`<a href="${leagueUrl(l,key)}" ${tab===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function standingsPage(l){const you=l.standings.find(r=>r.id===S.user.id),ordered=[...l.standings].sort((a,b)=>(ui.sort==='name'?a.name.localeCompare(b.name):ui.sort==='total'?a.total-b.total:a.rank-b.rank)*(ui.sortAsc?1:-1));return (l.status==='scheduled'?readiness(l):'')+`<div class="stat-strip"><div class="stat"><span>Your position</span><strong>${l.picks.length?'#'+you.rank:'—'}<small>of ${l.members.length} managers</small></strong></div><div class="stat"><span>Your points</span><strong>${you.total}<small>provisional total</small></strong></div><div class="stat"><span>Your roster</span><strong>${you.drafted}<small>of ${l.sports.length} sports filled</small></strong></div></div><section class="panel"><div class="section-head"><h2>League standings</h2>${link('Scoring rules',leagueUrl(l,'rules'),'ghost')}</div><div class="data-wrap"><table class="data-table"><caption>Updated ${date(l.updated)} · Equal totals share a rank. ${l.sample?'Illustrative sample results.':'Results entered by your commissioner.'}</caption><thead><tr>${[['rank','Rank'],['name','Manager'],['total','Points']].map(([k,label])=>`<th scope="col" ${ui.sort===k?`aria-sort="${ui.sortAsc?'ascending':'descending'}"`:''} class="${k==='total'?'numeric':''}"><button class="table-sort" data-action="sort" data-key="${k}">${label} ${ui.sort===k?(ui.sortAsc?'↑':'↓'):''}</button></th>`).join('')}<th scope="col" class="numeric secondary-col">Teams drafted</th></tr></thead><tbody>${ordered.map(r=>`<tr class="${r.id===S.user.id?'you':''}"><td class="rank">${l.picks.length?'#'+r.rank:'—'}</td><td><div class="person">${avatar(r.name,r.id===S.user.id)}<button class="text-link" data-action="breakdown" data-user="${r.id}">${e(r.name)}${r.id===S.user.id?'<span class="rank-badge">YOU</span>':''}</button></div></td><td class="numeric score-total">${r.total}</td><td class="numeric secondary-col">${r.drafted}/${l.sports.length}</td></tr>`).join('')}</tbody></table></div><p class="small muted section-space">Select a manager to see exactly where their points came from.</p></section>${!l.commissioner&&l.status==='scheduled'?`<div class="section-space">${button('Leave league','leave','ghost')}</div>`:''}`;}
function rosterPage(l){return `<div class="stack">${[...l.members].sort((a,b)=>(b.id===S.user.id)-(a.id===S.user.id)).map(m=>`<details class="roster-card" ${m.id===S.user.id?'open':''}><summary>${e(m.name)} ${m.id===S.user.id?'· You':''} <span class="muted small">· ${l.picks.filter(p=>p.userId===m.id).length}/${l.sports.length} teams</span></summary><div class="roster-grid">${l.sports.map(s=>{const p=l.picks.find(p=>p.userId===m.id&&p.team.sport===s);return `<div class="roster-team"><div><p class="eyebrow">${e(s)}</p><h3>${p?e(p.team.name):'Open slot'}</h3><p>${p?p.override!==null?'Commissioner score override':p.finish?`Finish #${p.finish} · ${Math.max(0,10-p.finish)} placement + ${p.finish===1?3:p.finish===2?1:0} bonus`:'Result pending':'Ready for your draft'}</p></div><span class="score-total">${p?p.points+' pts':'—'}</span></div>`;}).join('')}</div></details>`).join('')}</div>`;}
function resultsPage(l){const picks=l.picks.filter(p=>(!ui.pickSport||p.team.sport===ui.pickSport)&&(!ui.pickRound||Math.ceil(p.number/l.members.length)===+ui.pickRound)&&(`${p.team.name} ${l.members.find(m=>m.id===p.userId)?.name}`.toLowerCase().includes(ui.pickSearch.toLowerCase())));return `<section class="panel"><h2>Draft results</h2><div class="filter-bar section-space"><label class="field search-field"><span>Search picks</span><input type="search" id="pickSearch" data-filter="pickSearch" value="${e(ui.pickSearch)}" placeholder="Team or manager"></label>${select('pickSport','Sport',option('','All sports',ui.pickSport)+l.sports.map(s=>option(s,s,ui.pickSport)).join(''),'data-filter="pickSport"')}${select('pickRound','Round',option('','All rounds',ui.pickRound)+l.sports.map((_,i)=>option(i+1,`Round ${i+1}`,ui.pickRound)).join(''),'data-filter="pickRound"')}${button('Clear filters','clear-picks','ghost')}</div><p class="small muted">${picks.length} of ${l.picks.length} picks</p>${picks.length?`<div class="data-wrap"><table class="data-table"><caption class="sr-only">Draft history</caption><thead><tr><th scope="col">Pick</th><th scope="col">Team / sport</th><th scope="col">Manager</th><th scope="col" class="secondary-col">Round</th></tr></thead><tbody>${picks.map(p=>`<tr><td>${p.number}</td><td>${e(p.team.name)}<p class="small">${e(p.team.sport)}</p></td><td>${e(l.members.find(m=>m.id===p.userId)?.name)}</td><td class="secondary-col">${Math.ceil(p.number/l.members.length)}</td></tr>`).join('')}</tbody></table></div>`:empty(l.picks.length?'No picks match your filters':'No picks yet',l.picks.length?'Try a different search or clear the filters.':'Your draft history will appear after the first selection.',l.picks.length?button('Clear filters','clear-picks','ghost'):link('Prepare for draft',leagueUrl(l,'draft'),'primary'))}</section>`;}
function activityList(l,max=50){return l.activity.slice(0,max).map(a=>`<article class="activity-item"><span class="activity-dot">${icon('activity')}</span><div><p>${e(a.text)}</p><small>${e(a.actor)} · <time datetime="${new Date(a.at).toISOString()}">${date(a.at)}</time></small></div></article>`).join('');}
function rules(){return `<div class="rules-grid section-space"><section class="panel"><div class="section-head"><h2>Placement points</h2><span class="pill">Rules v1</span></div><div class="points-grid">${Array.from({length:9},(_,i)=>`<div class="points-cell"><span>Place ${i+1}</span><strong>${9-i}</strong><span>points</span></div>`).join('')}</div><p class="small muted section-space">10th place or lower earns 0 placement points.</p></section><section class="panel rules-copy"><h2>A little extra for going all the way.</h2><p><strong class="accent">+3 points</strong> for a champion. <strong class="accent">+1 point</strong> for a runner-up.</p><p>Example: 1st place (9) + champion bonus (3) = <strong>12 points</strong>.</p><hr class="divider"><h3>Drafting & ties</h3><p>One team per sport, per manager. Snake order reverses each round. Only the manager on the clock can pick.</p><p>At timeout: first eligible queued team, then the highest-ranked eligible team in the local catalog. Catalog order is illustrative.</p><p>Equal totals share a rank in this local edition. Results remain provisional; commissioner corrections include a reason in Activity.</p></section></div>`;}
function settingsPage(l){return `<div class="settings-grid"><div class="stack"><form class="panel" data-form="settings"><h2>League details</h2>${formError()}${field('name','League name',l.name,'text','required minlength="3" maxlength="120"')}${textArea('description','Description',l.description)}${l.status==='scheduled'?draftFields(l):'<p class="small muted">Draft settings are fixed after the draft starts. Pause to make pick corrections.</p>'}<label class="check-row"><input type="checkbox" name="locked" ${l.locked?'checked':''}>Lock membership (stop new invitations and joins)</label><div class="form-footer"><button class="button primary" type="submit">Save settings</button></div></form><section class="panel"><h2>Managers <small class="muted">${l.members.length}/${l.capacity}</small></h2><p class="small muted">${l.order==='manual'?'Use the arrows to set the starting order before drafting.':'Order is randomized when the draft starts.'}</p>${l.members.map((m,i)=>`<div class="member-row">${avatar(m.name)}<span>${e(m.name)} ${m.id===l.owner?'<small class="muted">· Commissioner</small>':''}</span>${l.status==='scheduled'&&l.order==='manual'?`${button(icon('up'),'order','icon-button ghost',`data-user="${m.id}" data-direction="up" aria-label="Move ${e(m.name)} up" ${i===0?'disabled':''}`)}${button(icon('down'),'order','icon-button ghost',`data-user="${m.id}" data-direction="down" aria-label="Move ${e(m.name)} down" ${i===l.members.length-1?'disabled':''}`)}`:''}${m.id!==l.owner&&l.status==='scheduled'?button(icon('close'),'remove','icon-button ghost',`data-user="${m.id}" aria-label="Remove ${e(m.name)}"`):''}</div>`).join('')}</section>${l.status==='complete'?scoreForm(l):''}</div><div class="stack"><form class="panel" id="invitations" tabindex="-1" data-form="invite"><h2>Invite your people</h2>${formError()}<p class="field-help">${emailCopy()}</p>${textArea('emails','Email addresses','','friend@example.com, rival@example.com')}<button class="button primary full" type="submit" ${l.status!=='scheduled'||l.locked?'disabled':''}>${emailEnabled()&&!S.user.sample?'Create invitations':'Create local invitations'}</button><div id="invite-results" class="section-space" role="status"></div>${l.outgoingInvitations?.length?`<hr class="divider"><h3>Invitation status</h3><div class="stack-sm section-space">${l.outgoingInvitations.map(i=>`<p class="small muted">${e(i.email)} · ${e(i.status)} · ${e(i.delivery)} ${i.delivery==='failed'?button('Retry delivery','retry-mail','ghost',`data-id="${i.id}" data-mutation`):''}</p>`).join('')}</div>`:''}</form><section class="panel"><h2>Draft controls</h2><p class="small muted">${l.members.length===l.capacity?'Your managers are ready.':'Fill every manager slot before starting.'} The commissioner starts the draft explicitly.</p><div class="button-row section-space">${draftControls(l)}${link('Open draft room',leagueUrl(l,'draft'),'ghost')}</div></section>${l.picks.length?`<section class="panel"><h2>Correct a pick</h2><p class="small muted">Pause a live draft first. Corrections must stay in the same sport and reset that pick’s score.</p><div class="section-space">${button('Correct a pick','correct','ghost',l.status==='live'?'disabled':'')}</div></section>`:''}<section class="panel danger-zone"><h2>League administration</h2><p>Changes here affect everyone. You’ll review the consequences before confirming.</p><div class="button-row">${button('Transfer commissioner','transfer','ghost',l.members.length<2?'disabled':'')}${button('Reset draft','reset','danger',!l.picks.length&&l.status==='scheduled'?'disabled':'')}</div></section></div></div>`;}
function scoreForm(l){return `<form class="panel" data-form="score"><h2>Record results & corrections</h2><p class="field-help">Local results are entered by the commissioner. Every change records its old value, new value, and your reason.</p>${formError()}${select('pickId','Drafted team',l.picks.map(p=>option(p.id,`${p.team.name} · ${l.members.find(m=>m.id===p.userId)?.name}`,'')).join(''))}${select('mode','Scoring method',option('finish','Placement + automatic bonus','finish')+option('override','Manual point override','finish'))}<div class="form-grid">${field('finish','Final place (blank = pending)','','number','min="1" max="32"')}${field('points','Override points',0,'number','min="0" max="100"')}</div>${field('reason','Reason / result source','','text','required minlength="5" maxlength="500"')}<button class="button primary" type="submit">Save result</button></form>`;}
function draftControls(l){if(!l.commissioner)return '';if(l.status==='complete')return status(l);return button(l.status==='live'?'Pause draft':l.status==='paused'?'Resume draft':'Start draft','draft-status',l.status==='live'?'ghost':'primary',`data-status="${l.status==='live'?'paused':'live'}" ${l.members.length!==l.capacity?'disabled':''}`);}
function accountPage(){return head('Account','Your profile, preferences, and security.','', 'MAKE YOURSELF AT HOME')+`<div class="settings-grid"><form class="panel" data-form="account"><h2>Profile & preferences</h2><hr class="divider">${formError()}${field('name','Display name',S.user.name,'text','required minlength="2" autocomplete="name" maxlength="120"')}${field('email','Account email',S.user.email,'email','readonly','Used for invitations. '+(S.user.verified?'Verified address.':'Not verified.'))}${select('zone','Display time zone',[...new Set([S.user.zone,...zones])].map(z=>option(z,z.replaceAll('_',' '),S.user.zone)).join(''))}<p class="field-help">Draft dates use this time zone. Changing it never changes the actual scheduled instant.</p><label class="check-row"><input type="checkbox" name="notifications" ${S.user.notifications?'checked':''}>Show an in-app alert when it becomes my turn</label><div class="form-footer"><button class="button primary" type="submit">Save preferences</button></div></form><div class="stack"><section class="panel"><h2>Security</h2>${!S.user.sample?`<div class="notice section-space">${S.user.verified?'✓ Email verified':'Email not verified'}${S.user.pendingEmail?` · Awaiting verification of ${e(S.user.pendingEmail)}`:''}<p>${emailCopy()}</p>${S.emailStatus?`<p>Latest email: ${e(S.emailStatus.status)}${S.emailStatus.error?' · '+e(S.emailStatus.error):''}</p>`:''}${emailEnabled()?`<div class="button-row">${button('Resend verification','verify-resend','ghost','data-mutation')}${button('Change email','email-change','ghost')}</div>`:''}</div>`:''}<p class="section-space small muted">${S.user.sample?'You’re exploring with an isolated sample account. No password was stored.':'Passwords are hashed on the local server. Sessions use an HttpOnly cookie. Recovery uses the code shown when you created your account.'}</p><div class="button-row section-space">${S.user.sample?button('Create personal account','signup','primary'):button('Change password','change-password','ghost')}${button('Sign out','logout','ghost','data-mutation')}</div></section><section class="panel"><h2>About this workspace</h2><p class="section-space small muted">This is the local edition of LOC. ${emailCopy()} Scores are entered by commissioners; no live sports feed is connected. Personal accounts start empty; sample accounts contain clearly labeled illustrative data.</p></section></div></div>`;}
function queuePanel(l){const q=(l.queues[S.user.id]||[]).map(id=>l.teams.find(t=>t.id===id)).filter(Boolean);return `<section class="panel queue-panel" id="draft-panel-queue"><div class="section-head"><h2>My queue <small>${q.length}</small></h2>${icon('grid')}</div><p class="small muted">Your first available, eligible team is picked at timeout.</p>${q.length?q.map((t,i)=>`<div class="queue-row" data-key="queue-${e(t.id)}"><span class="small muted">${i+1}</span><div><strong>${e(t.name)}</strong><p>${e(t.sport)}</p></div><div class="queue-actions">${button(icon('up'),'queue','icon-button ghost',`data-mutation data-team="${e(t.id)}" data-op="up" data-focus="q-up-${e(t.id)}" aria-label="Move ${e(t.name)} up" ${i===0?'disabled':''}`)}${button(icon('down'),'queue','icon-button ghost',`data-mutation data-team="${e(t.id)}" data-op="down" data-focus="q-down-${e(t.id)}" aria-label="Move ${e(t.name)} down" ${i===q.length-1?'disabled':''}`)}${button(icon('close'),'queue','icon-button ghost',`data-mutation data-team="${e(t.id)}" data-op="remove" data-focus="q-remove-${e(t.id)}" aria-label="Remove ${e(t.name)} from queue"`)}</div></div>`).join(''):empty('Make a shortlist','Select a team, then add it to your queue.')}<p class="small muted section-space">Empty queue? The clock chooses the highest-ranked eligible team in the illustrative local catalog.</p></section>`;}
function teamPool(l){const available=l.teams.filter(t=>!l.picks.some(p=>p.team.id===t.id));const pool=available.filter(t=>(ui.poolAll||l.eligibleIds.includes(t.id))&&(!ui.poolSport||ui.poolSport===t.sport)&&`${t.name} ${t.sport}`.toLowerCase().includes(ui.poolSearch.toLowerCase()));return `<section class="panel pool-panel" id="draft-panel-available"><div class="section-head"><h2>Available teams <small>${pool.length}</small></h2>${icon('search')}</div><div class="filter-bar">${select('poolSport','Sport',option('','All sports',ui.poolSport)+l.sports.map(s=>option(s,s,ui.poolSport)).join(''),'data-filter="poolSport"')}<label class="field search-field"><span>Search teams</span><input id="poolSearch" type="search" data-filter="poolSearch" value="${e(ui.poolSearch)}" placeholder="Team or sport"></label></div><label class="check-row"><input type="checkbox" data-filter="poolAll" ${ui.poolAll?'checked':''}>Show filled sport slots too</label><div class="pool-list">${pool.map(t=>`<button class="pool-row" type="button" data-action="select-team" data-team="${e(t.id)}" data-focus="team-${e(t.id)}" aria-pressed="${ui.selected===t.id}"><span class="team-token">${e(t.sport.slice(0,3))}</span><span class="team-info"><strong>${e(t.name)}</strong><small>${e(t.sport)} · ${l.eligibleIds.includes(t.id)?'Slot available':'Your sport slot is filled'}</small></span>${icon(ui.selected===t.id?'check':'plus')}</button>`).join('')||empty('No teams match','Try another search or clear your filters.',button('Clear filters','clear-pool','ghost'))}</div></section>`;}
function selection(l,sheet=false){const team=l.teams.find(t=>t.id===ui.selected),yourTurn=l.current?.id===S.user.id,available=team&&l.eligibleIds.includes(team.id),queued=team&&(l.queues[S.user.id]||[]).includes(team.id);return `<section class="panel selection-panel" id="${sheet?'selection-sheet':'selection'}"><p class="eyebrow">YOUR NEXT CONTENDER</p>${team?`<div class="selected-art">${icon('shield')}</div><span class="pill">${e(team.sport)}</span><h2 tabindex="-1" id="${sheet?'sheet-selected-title':'selected-title'}">${e(team.name)}</h2><p>${available?'Eligible for your '+e(team.sport)+' roster slot.':l.picks.some(p=>p.team.id===team.id)?'This team has already been drafted.':'Your '+e(team.sport)+' slot is already filled. '+link('View your roster',leagueUrl(l,'roster'),'ghost')}</p><div class="button-row">${button(`Draft ${e(team.name)}`,'pick','primary',`data-version="${l.version}" data-mutation ${!available||!yourTurn||l.status!=='live'?'disabled':''}`)}${button(queued?'Remove from queue':'Add to queue','queue','ghost',`data-team="${e(team.id)}" data-op="${queued?'remove':'add'}" data-mutation ${!available||l.status==='complete'?'disabled':''}`)}</div><p>${l.status==='scheduled'?'Prepare your queue now. Picking opens when the draft starts.':l.status==='paused'?'Draft paused. Your queue stays available.':!yourTurn?`${e(l.current?.name||'Draft complete')}${l.current?' is picking.':''} ${turnHint(l)}`:'This choice fills your sport slot. Review the team name before submitting.'}</p>`:empty('Choose your contender','Select a team from the list to see your next move.')}<hr class="divider"><h3>Your roster slots</h3><div class="draft-roster-slots">${l.sports.map(s=>{const filled=l.picks.some(p=>p.userId===S.user.id&&p.team.sport===s);return `<span class="slot ${filled?'filled':''}">${filled?'✓':'○'} ${e(s)}</span>`;}).join('')}</div></section>`;}
function board(l){return `<section class="panel draft-secondary" id="draft-panel-board"><div class="section-head"><h2>Draft board</h2><span class="small muted">${l.picks.length}/${l.members.length*l.sports.length} picks</span></div><div class="data-wrap" tabindex="0" aria-label="Draft board, scroll horizontally"><table class="data-table board-table"><caption>Snake draft order reverses each round.</caption><thead><tr><th scope="col">Round</th>${l.members.map(m=>`<th scope="col">${e(m.name)}${m.id===S.user.id?' (You)':''}</th>`).join('')}</tr></thead><tbody>${l.sports.map((_,round)=>`<tr><th scope="row">${round+1}</th>${l.members.map((m,i)=>{const number=round*l.members.length+(round%2?l.members.length-i:i+1),p=l.picks.find(p=>p.number===number);return `<td class="${l.status==='live'&&l.picks.length+1===number?'current':''}"><small>Pick ${number}</small><strong>${p?e(p.team.name):'—'}</strong><small>${p?e(p.team.sport):''}</small></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function draftPage(l){if(l.status==='complete')return shell(leagueHeader(l,'results')+`<section class="panel">${empty('The draft is complete','Your contenders are locked in. Follow their progress in the standings.',link('View standings',leagueUrl(l),'primary')+link('Review your roster',leagueUrl(l,'roster'),'ghost'))}</section>`+board(l));return `<main id="main" class="draft-page" data-draft-tab="${ui.draftTab}"><header class="draft-header"><div><a class="text-link" href="${leagueUrl(l)}">${icon('back')} Back to league</a><h1 tabindex="-1">${e(l.name)} <span class="sample-label">${l.sample?'· Sample':''}</span></h1><p>Snake draft · Round ${Math.floor(l.picks.length/l.members.length)+1} of ${l.sports.length} · Pick ${l.picks.length+1} of ${l.members.length*l.sports.length}</p></div><div class="button-row">${status(l)}${draftControls(l)}${l.commissioner?button('Commissioner override','override','ghost',l.status!=='live'?'disabled':''):''}</div></header><div class="draft-clock-bar ${l.current?.id===S.user.id&&l.status==='live'?'your-turn':''}"><div class="clock-side">${avatar(l.current?.name||'LOC',true)}<div><div class="clock-label">${l.status==='scheduled'?'DRAFT LOBBY':l.status==='paused'?'DRAFT PAUSED':l.current?.id===S.user.id?'YOUR TURN':'ON THE CLOCK'}</div><strong>${l.status==='scheduled'?date(l.scheduled):e(l.current?.name)}</strong><p class="small">${l.status==='live'?turnHint(l):'Prepare your queue while you wait.'}</p></div></div><div><div class="clock-number" id="clock" aria-label="Time remaining">—</div><div class="clock-label">${l.status==='scheduled'?'Prepare your queue':l.status==='paused'?'Clock stopped':'seconds remaining'}</div></div></div><div class="tab-strip draft-work-tabs" role="tablist" aria-label="Draft workspace">${[['available','Available'],['queue','Queue'],['board','Board'],['chat','Chat']].map(([key,label])=>`<button class="button ghost" type="button" role="tab" id="draft-tab-${key}" aria-selected="${ui.draftTab===key}" aria-controls="draft-panel-${key}" tabindex="${ui.draftTab===key?0:-1}" data-action="draft-tab" data-tab="${key}">${label}</button>`).join('')}</div><div id="draft-workspace" class="draft-columns">${teamPool(l)}${selection(l)}${queuePanel(l)}</div>${board(l)}<div class="draft-bottom-grid" id="draft-panel-chat"><section class="panel"><h2>League chat</h2><div class="chat-list">${l.chat.map(m=>`<div class="chat-message"><strong>${e(m.name)}</strong><time>${date(m.at)}</time><p>${e(m.text)}</p></div>`).join('')||empty('Room for a little rivalry','Messages stay within this league on the local server.')}</div><form class="chat-form" data-form="chat">${field('text','Message your league','','text','required maxlength="500" placeholder="Say something…"')}<button class="button primary" type="submit">Send</button>${formError()}</form></section><section class="panel"><h2>Recent activity</h2>${activityList(l,5)}</section></div></main>`;}
function render({preserve=false}={}){renderEpoch++;const focus=preserve?document.activeElement:null,key=focus?.dataset.focus,inputId=focus?.id,selectionStart=focus?.selectionStart,selectionEnd=focus?.selectionEnd,scroll=scrollY,poolScroll=$('.pool-list')?.scrollTop||0;let html;const l=league();if(l&&ui.filtersLeague!==l.id){saveFilters();loadFilters(l.id);}if(!S.user){html=landing();document.title='League of Champions';}else if(route.includes('/draft')&&l){html=draftPage(l);document.title=`Draft · ${l.name} · LOC`;}else{let page;if(route==='/leagues/new')page=createPage();else if(route==='/leagues')page=leaguesPage();else if(route==='/invitations')page=invitationsPage();else if(route==='/account')page=accountPage();else if(route.startsWith('/leagues/')){if(!l)page=head('League unavailable','This league may have been removed or your membership changed.',link('Back to my leagues','/leagues','primary'));else{if(ui.filtersLeague!==l.id){ui.filtersLeague=l.id;ui.pickSearch='';ui.pickRound='';ui.pickSport='';ui.poolSearch='';ui.poolSport='';ui.selected=null;}const tab=route.split('/')[3]||'standings';page=leagueHeader(l,tab)+({standings:()=>standingsPage(l),roster:()=>rosterPage(l),results:()=>resultsPage(l),activity:()=>`<section class="panel"><h2>League activity</h2>${activityList(l)}</section>`,rules,settings:()=>l.commissioner?settingsPage(l):empty('Commissioner access only','Return to standings to follow your league.',link('View standings',leagueUrl(l),'primary'))}[tab]||(()=>standingsPage(l)))();}}else page=home();html=shell(page);document.title=`${l?l.name:({'/home':'Home','/leagues':'My leagues','/leagues/new':'Create league','/account':'Account','/invitations':'Invitations'}[route]||'Home')} · LOC`;}if(preserve)reconcile(app,html);else app.innerHTML=html;restoreForms();saveFilters();const setup=$('#setup-summary');if(setup){const form=setup.closest('form'),n=form.querySelectorAll('[name=sports]:checked').length;setup.textContent=n?`${form.elements.capacity.value} managers × ${n} sports = ${+form.elements.capacity.value*n} picks. Each manager drafts one team per sport.`:'Choose your sports to see your draft size.';}if(!connected){connected=true;setConnected(false);}if(preserve){const target=key?[...document.querySelectorAll('[data-focus]')].find(el=>el.dataset.focus===key):inputId?document.getElementById(inputId):null;if(target){(target.disabled?target.parentElement.querySelector("button:not(:disabled)"):target)?.focus({preventScroll:true});if(typeof selectionStart==='number'&&target.setSelectionRange)try{target.setSelectionRange(selectionStart,selectionEnd);}catch{}}if($('.pool-list'))$('.pool-list').scrollTop=poolScroll;window.scrollTo(0,scroll);}syncDraftPanelSemantics(document,draftMobile.matches);tick();}

function forgotDialog(){showDialog('Reset your password',`<p>Request a one-time link that expires in 30 minutes. ${emailCopy()}</p><form data-form="forgot">${formError()}${field('email','Account email','','email','required autocomplete="email"')}<button class="button primary" type="submit">Send reset link</button></form>${button('Use recovery code','recovery-code','ghost')}`);}
function emailLinkDialog(hash=location.hash){const params=new URLSearchParams(hash.slice(1)),verify=params.get('verify'),reset=params.get('reset');if(!verify&&!reset)return;history.replaceState({},'',location.pathname);showDialog(verify?'Verify your email':'Choose a new password',`<p>${verify?'Confirm this email address for your LOC account.':'This link can be used once and expires after 30 minutes.'}</p><form data-form="email-link" data-kind="${verify?'verify':'reset-link'}">${formError()}<input type="hidden" name="token" value="${e(verify||reset)}">${reset?field('password','New password','','password','required minlength="10" maxlength="128" autocomplete="new-password"'):''}<button class="button primary" type="submit">${verify?'Verify email':'Save password'}</button></form>${verify?(S.user?button('Request a new link','verify-resend','ghost'):button('Sign in to request a new link','login','ghost')):button('Request a new reset link','forgot','ghost')}`);}

function authDialog(mode='login'){const signup=mode==='signup',reset=mode==='reset';showDialog(signup?'Create your local account':reset?'Recover your account':'Welcome back',`<p>${signup?'Start with a clean slate. No sample leagues will be added.':reset?'Use your saved recovery code to choose a new password. This local edition does not send password-reset emails.':'Sign in to your leagues on this computer.'}</p><form data-form="auth" data-mode="${mode}">${formError()}${signup?field('name','Your name','','text','required minlength="2" maxlength="120" autocomplete="name"'):''}${field('email','Email address','','email','required autocomplete="email" placeholder="you@example.com"')}${reset?field('recovery','Recovery code','','text','required autocomplete="off"'):''}${field('password',reset?'New password':'Password','','password',`required ${signup||reset?'minlength="10"':''} maxlength="128" autocomplete="${signup||reset?'new-password':'current-password'}"`,signup||reset?'Use at least 10 characters. A long passphrase works well.':'')}${!reset?'<label class="check-row"><input type="checkbox" name="remember">Keep me signed in for 30 days</label>':''}<button class="button primary full section-space" type="submit">${signup?'Create account':reset?'Reset password':'Sign in'}</button></form><div class="button-row section-space">${button(signup?'Already have an account? Sign in':'Create account',signup?'login':'signup','ghost')}${!signup&&!reset?button('Forgot password?','forgot','ghost'):''}</div><p class="small muted section-space">${emailCopy()}</p>`);}
function confirmDialog(title,description,action,fields='',label='Confirm',danger=true){showDialog(title,`<p>${description}</p><form data-form="confirm" data-kind="${action}">${formError()}${fields}<div class="form-footer">${button('Cancel','close','ghost')}<button class="button ${danger?'danger':'primary'}" type="submit">${label}</button></div></form>`);}
function breakdown(l,userId){const m=l.members.find(m=>m.id===userId),picks=l.picks.filter(p=>p.userId===userId);showDialog(`${m.name} · points breakdown`,`${picks.length?`<div class="stack-sm">${picks.map(p=>`<div class="roster-team"><div><h3>${e(p.team.name)}</h3><p>${e(p.team.sport)} · ${p.override!==null?'Commissioner override — see Activity':p.finish?`${Math.max(0,10-p.finish)} placement + ${p.finish===1?3:p.finish===2?1:0} bonus`:'Result pending'}</p></div><strong>${p.points} pts</strong></div>`).join('')}</div>`:empty('No picks yet','This roster will fill during the draft.')}<p class="small muted section-space">Total: ${picks.reduce((s,p)=>s+p.points,0)} points · Provisional<br>Updated ${date(l.updated)}. Equal totals share a rank.</p><div class="form-footer">${button('Close','close','primary')}</div>`);}
function correctionFields(l){return `${select('pickId','Pick to correct',l.picks.map(p=>option(p.id,`${p.team.name} · ${l.members.find(m=>m.id===p.userId)?.name}`,'')).join(''),'data-correction-pick')}${select('teamId','Replacement team',[])}${field('reason','Reason','','text','required minlength="5" maxlength="500"')}`;}
function updateCorrectionOptions(){const l=league(),p=l.picks.find(p=>p.id===$('#pickId',dialog)?.value);if(!p)return;$('#teamId',dialog).innerHTML=l.teams.filter(t=>t.sport===p.team.sport&&!l.picks.some(p=>p.team.id===t.id)).map(t=>option(t.id,t.name,'')).join('');}
document.addEventListener('click',async event=>{const a=event.target.closest('a');if(a&&a.origin===location.origin&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&event.button===0&&!a.getAttribute('href').startsWith('#')){event.preventDefault();navigate(a.pathname+a.search+a.hash);return;}const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,l=league();
  if(action==='close')closeDialog();else if(action==='login'||action==='signup'){if(b.dataset.intent)keepIntent(b.dataset.intent);authDialog(action);}else if(action==='forgot'){if(emailEnabled())forgotDialog();else authDialog('reset');}
  else if(action==='recovery-code')authDialog('reset');
  else if(action==='verify-resend')await mutate('/api/account/resend',{},()=>{render({preserve:true});toast(S.emailMode==='preview'?'Verification written to the testing mailbox.':'Verification email queued.');});
  else if(action==='email-change')showDialog('Change account email',`<p>Your current email stays active until you verify the new address.</p><form data-form="email-change">${formError()}${field('email','New email address','','email','required autocomplete="email"')}${field('password','Current password','','password','required autocomplete="current-password"')}<button class="button primary" type="submit">Send verification link</button></form>`);
  else if(action==='demo')await mutate('/api/auth/demo',{},()=>navigate('/home'));
  else if(action==='logout')await mutate('/api/auth/logout',{},()=>navigate('/'));
  else if(action==='clear-league'){ui.leagueSearch='';render({preserve:true});}
  else if(action==='clear-picks'){ui.pickSearch='';ui.pickSport='';ui.pickRound='';render({preserve:true});}
  else if(action==='clear-pool'){ui.poolSearch='';ui.poolSport='';ui.poolAll=false;render({preserve:true});}
  else if(action==='sort'){ui.sortAsc=ui.sort===b.dataset.key?!ui.sortAsc:true;ui.sort=b.dataset.key;render({preserve:true});}
  else if(action==='breakdown')breakdown(l,b.dataset.user);
  else if(action==='invite-decline'){await mutate('/api/invitations',{id:b.dataset.id,action:'decline'},()=>{render({preserve:true});toast('Invitation declined.',`<button class="text-link" data-action="invite-undo" data-id="${b.dataset.id}">Undo</button>`);});}
  else if(action==='invite-undo'){await mutate('/api/invitations',{id:b.dataset.id,action:'undo'},()=>{render({preserve:true});toast('Invitation restored.');});}
  else if(action==='retry-mail')await mutate(`/api/leagues/${l.id}/retrymail`,{inviteId:b.dataset.id},()=>{render({preserve:true});toast('Delivery queued for retry.');});
  else if(action==='retry-connection')await refresh(true);
  else if(action==='invite-accept'){const invite=S.invitations.find(i=>i.id===b.dataset.id);await mutate('/api/invitations',{id:b.dataset.id,action:'accept'},()=>{navigate(`/leagues/${invite.leagueId}/standings`);toast(`You’re in ${invite.league.name}.`);});}
  else if(action==='select-team'){ui.selected=b.dataset.team;render({preserve:true});if(matchMedia('(max-width:760px)').matches){showDialog('Your next contender',`<div id="selection-live"><p class="small muted">${l.status==='live'?(l.current?.id===S.user.id?'Your turn':'Waiting for '+e(l.current?.name)):l.status==='paused'?'Draft paused':'Draft scheduled'} · <span data-selection-clock></span></p>`+selection(l,true)+'</div>');tick();}}
  else if(action==='draft-tab'){ui.draftTab=b.dataset.tab;render({preserve:true});$(`#draft-tab-${ui.draftTab}`)?.focus({preventScroll:true});}
  else if(action==='queue'){const teamName=l.teams.find(t=>t.id===b.dataset.team)?.name;await mutate(`/api/leagues/${l.id}/queue`,{teamId:b.dataset.team,action:b.dataset.op},()=>{render({preserve:true});const position=(league().queues[S.user.id]||[]).indexOf(b.dataset.team)+1;announce(b.dataset.op==='remove'?`${teamName} removed from your queue.`:`${teamName} is now at position ${position} in your queue.`);if(dialog.open&&$('.selection-panel',dialog))closeDialog();const control=[...document.querySelectorAll('.queue-panel [data-focus]')].find(el=>el.dataset.focus===b.dataset.focus);if(control)(control.disabled?control.parentElement.querySelector('button:not(:disabled)'):control)?.focus({preventScroll:true});else if(b.dataset.op==='remove')$('.queue-panel button:not(:disabled)')?.focus({preventScroll:true});});}
  else if(action==='pick'){const team=l.teams.find(t=>t.id===ui.selected);await mutate(`/api/leagues/${l.id}/pick`,{teamId:ui.selected,version:+b.dataset.version},()=>{ui.selected=null;if(dialog.open)closeDialog();render();toast(`You drafted ${team.name} · ${team.sport}.`);$('#poolSearch')?.focus({preventScroll:true});});}
  else if(action==='draft-status'){const target=b.dataset.status;confirmDialog(target==='paused'?'Pause the draft?':l.status==='paused'?'Resume the draft?':'Start the draft?',target==='paused'?'The shared clock will stop for all managers. Their queues are preserved.':`All ${l.members.length} managers will enter the timed draft. Each pick allows ${l.timer} seconds. Empty queues use the highest-ranked eligible team in the illustrative local catalog.`, 'status',`<input type="hidden" name="status" value="${target}">`,target==='paused'?'Pause draft':l.status==='paused'?'Resume draft':'Start draft',false);}
  else if(action==='reset')confirmDialog(`Reset ${l.name}?`,`This removes ${l.picks.length} picks and all roster scores and queues. Membership, messages, and league rules remain. This cannot be undone.`,'reset',field('reason','Reason','','text','required minlength="5" maxlength="500"'),'Reset draft');
  else if(action==='leave')confirmDialog(`Leave ${l.name}?`,'You will lose league access. You can return only if the commissioner invites you again.','leave','','Leave league');
  else if(action==='remove')confirmDialog('Remove manager?',`${e(l.members.find(m=>m.id===b.dataset.user)?.name)} will lose access and their queue. They can be invited again before the draft.`, 'remove',`<input type="hidden" name="memberId" value="${b.dataset.user}">`,'Remove manager');
  else if(action==='transfer')confirmDialog('Transfer commissioner role?','The new commissioner will control settings, members, drafting, and scores. You will remain a manager.','transfer',select('memberId','New commissioner',l.members.filter(m=>m.id!==S.user.id).map(m=>option(m.id,m.name,'')).join('')),'Transfer role');
  else if(action==='order')await mutate(`/api/leagues/${l.id}/order`,{memberId:b.dataset.user,direction:b.dataset.direction},()=>{render({preserve:true});announce('Draft order updated.');});
  else if(action==='override'){confirmDialog('Draft on behalf of another manager',`You are choosing for ${e(l.current.name)}. This override will be recorded in Activity.`, 'pick',`<input type="hidden" name="override" value="true"><input type="hidden" name="version" value="${l.version}">${select('teamId','Team',l.teams.filter(t=>!l.picks.some(p=>p.team.id===t.id||(p.userId===l.current.id&&p.team.sport===t.sport))).map(t=>option(t.id,`${t.name} · ${t.sport}`,'')).join(''))}${field('reason','Override reason','','text','required minlength="5" maxlength="500"')}`,'Confirm override');}
  else if(action==='correct'){confirmDialog('Correct a draft pick','Choose an undrafted team in the same sport. Its result will return to pending. The correction will be recorded in Activity.','correct',correctionFields(l),'Save correction');updateCorrectionOptions();}
  else if(action==='change-password')showDialog('Change password',`<form data-form="password">${formError()}${field('currentPassword','Current password','','password','required autocomplete="current-password"')}${field('password','New password','','password','required minlength="10" maxlength="128" autocomplete="new-password"','Use at least 10 characters.')}<button class="button primary" type="submit">Change password</button></form>`);
  else if(action==='recovery-done'){closeDialog();navigate(intended);keepIntent('/home');}
});
document.addEventListener('input',event=>{const input=event.target;rememberForm(input.form);if(input.hasAttribute('data-filter')&&input.type!=='checkbox'&&input.tagName!=='SELECT'){ui[input.dataset.filter]=input.value;render({preserve:true});}if(input.hasAttribute('data-summary')){const form=input.form;const n=form.querySelectorAll('[name=sports]:checked').length,capacity=+form.elements.capacity.value;$('#setup-summary').textContent=n?`${capacity} managers × ${n} sports = ${capacity*n} picks. Each manager drafts one team per sport.`:'Choose your sports to see your draft size.';}clearFieldError(input);});
document.addEventListener('change',event=>{const input=event.target;rememberForm(input.form);if(input.hasAttribute('data-filter')){ui[input.dataset.filter]=input.type==='checkbox'?input.checked:input.value;render({preserve:true});}if(input.hasAttribute('data-league-switch'))navigate(`/leagues/${input.value}/standings`);if(input.hasAttribute('data-correction-pick'))updateCorrectionOptions();});
document.addEventListener('keydown',event=>{if(event.target.getAttribute('role')!=='tab')return;const tabs=[...event.target.parentElement.querySelectorAll('[role=tab]')];let idx=tabs.indexOf(event.target);if(event.key==='ArrowRight')idx=(idx+1)%tabs.length;else if(event.key==='ArrowLeft')idx=(idx+tabs.length-1)%tabs.length;else if(event.key==='Home')idx=0;else if(event.key==='End')idx=tabs.length-1;else return;event.preventDefault();tabs[idx].click();});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();if(busy)return;const data=Object.fromEntries(new FormData(form)),kind=form.dataset.form,l=league();$('.form-error',form)?.replaceChildren();[...form.elements].forEach(clearFieldError);try{
  if(kind==='auth'){data.remember=!!data.remember;data.zone=Intl.DateTimeFormat().resolvedOptions().timeZone;const mode=form.dataset.mode;await mutate(`/api/auth/${mode}`,data,result=>{closeDialog();if(result.recovery)showDialog('Save your recovery code',`<p>Keep this code somewhere private. You need it if you forget your password. It is shown only once. ${emailEnabled()?'You can also use an emailed reset link. Check Account for verification status.':'No email will be sent.'}</p><code class="recovery-code">${e(result.recovery)}</code>${button('I saved my recovery code','recovery-done','primary full')}`);else {navigate(intended);keepIntent('/home');}},form);}
  else if(kind==='forgot')await mutate('/api/auth/forgot',data,()=>{closeDialog();toast('If that account exists, a reset link has been queued.');},form);
  else if(kind==='email-change')await mutate('/api/account/email',data,()=>{closeDialog();render({preserve:true});toast('Verify the new address to complete the change.');},form);
  else if(kind==='email-link')await mutate('/api/auth/'+form.dataset.kind,data,result=>{closeDialog();render();if(result.recovery)showDialog('Save your new recovery code',`<p>Your previous recovery code no longer works. Store this one privately.</p><code class="recovery-code">${e(result.recovery)}</code>${button('I saved my recovery code','recovery-done','primary')}`);else toast('Email verified.');},form);
  else if(kind==='create'){data.sports=new FormData(form).getAll('sports');data.scheduled=toInstant(data.scheduled);const key='loc-create-request:'+S.user.id,payload=JSON.stringify(data);let previous;try{previous=JSON.parse(sessionStorage.getItem(key));}catch{}data.requestId=previous?.payload===payload?previous.id:crypto.randomUUID();sessionStorage.setItem(key,JSON.stringify({id:data.requestId,payload}));await mutate('/api/leagues',data,result=>{sessionStorage.removeItem(key);navigate(`/leagues/${result.createdId}/standings`);toast(`${data.name} is ready. Invite your managers next.`);},form);}
  else if(kind==='settings'){data.locked=!!data.locked;data.scheduled=toInstant(data.scheduled);await mutate(`/api/leagues/${l.id}/settings`,data,()=>{render({preserve:true});toast('League settings saved.');},form);}
  else if(kind==='account'){data.notifications=!!data.notifications;await mutate('/api/account',data,()=>{render({preserve:true});toast('Preferences saved.');},form);}
  else if(kind==='password')await mutate('/api/account/password',data,()=>{closeDialog();toast('Password changed. Other sessions were signed out.');},form);
  else if(kind==='invite')await mutate(`/api/leagues/${l.id}/invite`,data,result=>{$('#invite-results').innerHTML=result.inviteResults.map(r=>`<p class="${r.status==='failed'?'field-error':'small'}">${e(r.email)} — ${r.status==='failed'?e(r.reason):r.status==='pending'?'Email queued — check delivery status below':'Available in local app · no email sent'}</p>`).join('');form.elements.emails.value=result.inviteResults.filter(r=>r.status==='failed').map(r=>r.email).join(', ');toast('Invitations updated. Review the results below.');},form);
  else if(kind==='score')await mutate(`/api/leagues/${l.id}/score`,data,()=>{render({preserve:true});toast('Result saved. Standings recalculated.');},form);
  else if(kind==='chat')await mutate(`/api/leagues/${l.id}/chat`,data,()=>{render({preserve:true});$('#text')?.focus({preventScroll:true});},form);
  else if(kind==='confirm'){const action=form.dataset.kind;if(data.version)data.version=+data.version;if(data.override)data.override=true;await mutate(`/api/leagues/${l.id}/${action}`,data,()=>{closeDialog();if(action==='leave')navigate('/leagues');else if(action==='transfer')navigate(leagueUrl(l));else render({preserve:true});toast({reset:'Draft reset. Rosters and scores cleared.',status:'Draft state updated.',remove:'Manager removed.',transfer:'Commissioner role transferred.',leave:'You left the league.',correct:'Pick corrected. Result returned to pending.',pick:'Commissioner pick recorded.'}[action]||'Saved.');},form);}
}catch(error){showError(form,error);}});
window.addEventListener('popstate',()=>navigate(location.pathname,{restore:true}));
function tick(){const clock=$('#clock'),l=league();if(!clock||!l)return;const remaining=l.status==='live'?Math.max(0,Math.ceil((l.deadline-Date.now()-offset)/1000)):l.status==='paused'?Math.ceil(l.remaining/1000):null;clock.textContent=remaining===null?'—':`${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}`;const sheetClock=document.querySelector('[data-selection-clock]');if(sheetClock)sheetClock.textContent=clock.textContent;if(remaining!==null&&remaining<=10&&l.status==='live'&&l.current?.id===S.user.id&&S.user.notifications&&tick.warned!==l.id+':'+l.version){tick.warned=l.id+':'+l.version;announce('Ten seconds or less remain for your pick.');}}
async function refresh(force=false){if(busy&&!force)return;try{const result=await request('/api/state');const old=S,changed=result.revision!==S.revision;pendingRender ||= changed;updateState(result);setConnected(true);reconcileSelection();if(old.user&&!result.user){keepIntent(route);render();authDialog('login');return;}if(route==='/account'&&old.emailStatus?.status!==S.emailStatus?.status)render({preserve:true});const l=league(),oldLeague=l&&old.leagues.find(x=>x.id===l.id);if(l?.status==='live'&&l.current?.id===S.user?.id&&oldLeague?.current?.id!==S.user?.id&&S.user.notifications){announce('It is your turn to draft.');toast('You’re on the clock. Choose your next contender.');}const active=document.activeElement,editing=active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName)&&!active.dataset.filter;const hasEditableForm=!!document.querySelector('form[data-form="create"],form[data-form="settings"],form[data-form="account"],form[data-form="score"]');if(hasEditableForm&&!editing&&pendingRender&&!dialog.open){render({preserve:true});pendingRender=false;}if((force||pendingRender)&&!dialog.open&&!editing&&!hasEditableForm){render({preserve:true});pendingRender=false;}tick();}catch{setConnected(false);}}
async function boot(){const emailHash=location.hash;try{updateState(await request('/api/state'));if(S.user&&route==='/')navigate('/home',{replace:true});else{render();if(!S.user&&route!=='/'){keepIntent(route);authDialog('login');}}emailLinkDialog(emailHash);}catch{app.innerHTML=`<main id="main" class="boot"><h1>Couldn’t reach your workspace</h1><p>Start the local server, then reload. Your saved leagues are still on this computer.</p><a class="button primary" href="/">Try again</a></main>`;}}
window.addEventListener('offline',()=>setConnected(false));window.addEventListener('online',()=>refresh(true));
boot();setInterval(tick,1000);setInterval(()=>refresh(),2000);
